-- Cập nhật Cấp độ tiếp cận phương tiện (cap_do_tiep_can)
-- Cấp 1: Xe lớn (16/29/45 chỗ), Ô tô, Xe máy (có bãi đỗ xe lớn, đường rộng)
-- Cấp 2: Ô tô, Xe máy (đường chính, không đỗ được xe lớn)
-- Cấp 3: Chỉ xe máy, xe đạp, đi bộ (ngõ/hẻm nhỏ, phố cổ chật hẹp)
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID('DIA_DIEM') AND name = 'cap_do_tiep_can')
BEGIN
    ALTER TABLE DIA_DIEM ADD cap_do_tiep_can INT DEFAULT 3;
END;

-- Cấp 1 (Xe lớn được phép):
UPDATE DIA_DIEM SET cap_do_tiep_can = 1 WHERE id IN (1, 2, 3, 4, 5, 27, 28, 29);

-- Cấp 2 (Ô tô cá nhân):
UPDATE DIA_DIEM SET cap_do_tiep_can = 2 WHERE id IN (6, 7, 8, 9, 11, 17, 20, 21, 23, 24, 25, 26, 30);

-- Cấp 3 (Chỉ xe máy, xe đạp, đi bộ):
UPDATE DIA_DIEM SET cap_do_tiep_can = 3 WHERE id IN (10, 12, 13, 14, 15, 16, 18, 19, 22);

GO

-- ============================================================
-- MIGRATION V2 (Thanh - Data/Database) cho SQL Server
-- Chay SAU DuLichThongMinh.sql. KHONG xoa cot/bang cu -> main.py van chay.
-- Chay lai nhieu lan an toan (IF COL_LENGTH / IF OBJECT_ID).
-- ============================================================
USE DuLichThongMinh;
GO

IF COL_LENGTH('DIA_DIEM','dia_chi') IS NULL ALTER TABLE DIA_DIEM ADD dia_chi NVARCHAR(500);
IF COL_LENGTH('DIA_DIEM','nhom_chinh') IS NULL ALTER TABLE DIA_DIEM ADD nhom_chinh NVARCHAR(30);
IF COL_LENGTH('DIA_DIEM','trong_nha_ngoai_troi') IS NULL ALTER TABLE DIA_DIEM ADD trong_nha_ngoai_troi NVARCHAR(20);
IF COL_LENGTH('DIA_DIEM','rating') IS NULL ALTER TABLE DIA_DIEM ADD rating FLOAT;
IF COL_LENGTH('DIA_DIEM','so_luot_danh_gia') IS NULL ALTER TABLE DIA_DIEM ADD so_luot_danh_gia INT;
IF COL_LENGTH('DIA_DIEM','muc_gia') IS NULL ALTER TABLE DIA_DIEM ADD muc_gia INT;
IF COL_LENGTH('DIA_DIEM','gia_tu') IS NULL ALTER TABLE DIA_DIEM ADD gia_tu INT;
IF COL_LENGTH('DIA_DIEM','gia_den') IS NULL ALTER TABLE DIA_DIEM ADD gia_den INT;
IF COL_LENGTH('DIA_DIEM','gia_ghi_chu') IS NULL ALTER TABLE DIA_DIEM ADD gia_ghi_chu NVARCHAR(255);
IF COL_LENGTH('DIA_DIEM','google_data_id') IS NULL ALTER TABLE DIA_DIEM ADD google_data_id NVARCHAR(100);
IF COL_LENGTH('DIA_DIEM','sdt') IS NULL ALTER TABLE DIA_DIEM ADD sdt VARCHAR(30);
IF COL_LENGTH('DIA_DIEM','website') IS NULL ALTER TABLE DIA_DIEM ADD website NVARCHAR(500);
IF COL_LENGTH('DIA_DIEM','thoi_gian_tham_quan_nguon') IS NULL ALTER TABLE DIA_DIEM ADD thoi_gian_tham_quan_nguon NVARCHAR(50) DEFAULT N'uoc_luong_chua_xac_minh';
IF COL_LENGTH('DIA_DIEM','trang_thai_du_lieu') IS NULL ALTER TABLE DIA_DIEM ADD trang_thai_du_lieu NVARCHAR(30) DEFAULT N'chua_xac_minh';
IF COL_LENGTH('DIA_DIEM','ghi_chu_kiem_tra') IS NULL ALTER TABLE DIA_DIEM ADD ghi_chu_kiem_tra NVARCHAR(MAX);
IF COL_LENGTH('DIA_DIEM','nguon_du_lieu') IS NULL ALTER TABLE DIA_DIEM ADD nguon_du_lieu NVARCHAR(100);
IF COL_LENGTH('DIA_DIEM','ngay_cap_nhat') IS NULL ALTER TABLE DIA_DIEM ADD ngay_cap_nhat DATE;
IF COL_LENGTH('CUA_SO_THOI_GIAN','thu') IS NULL ALTER TABLE CUA_SO_THOI_GIAN ADD thu INT;
IF COL_LENGTH('CUA_SO_THOI_GIAN','da_xac_minh') IS NULL ALTER TABLE CUA_SO_THOI_GIAN ADD da_xac_minh BIT DEFAULT 0;
IF COL_LENGTH('CUA_SO_THOI_GIAN','nguon') IS NULL ALTER TABLE CUA_SO_THOI_GIAN ADD nguon NVARCHAR(50);
GO

IF OBJECT_ID('DIA_DIEM_ANH') IS NULL CREATE TABLE DIA_DIEM_ANH (
    id INT IDENTITY(1,1) PRIMARY KEY, dia_diem_id INT NOT NULL, url NVARCHAR(MAX) NOT NULL,
    thu_tu INT DEFAULT 0, la_anh_bia BIT DEFAULT 0, nguon NVARCHAR(50),
    CONSTRAINT FK_Anh_DiaDiem FOREIGN KEY (dia_diem_id) REFERENCES DIA_DIEM(id));
IF OBJECT_ID('DIA_DIEM_REVIEW') IS NULL CREATE TABLE DIA_DIEM_REVIEW (
    id INT IDENTITY(1,1) PRIMARY KEY, dia_diem_id INT NOT NULL, noi_dung NVARCHAR(MAX) NOT NULL, so_sao FLOAT,
    nguoi_viet NVARCHAR(150), thoi_gian_goc NVARCHAR(50), tuoi_review_thang FLOAT, ngon_ngu NVARCHAR(10),
    so_ky_tu INT, dung_cho_ai BIT DEFAULT 0, nguon NVARCHAR(50),
    CONSTRAINT FK_Review_DiaDiem FOREIGN KEY (dia_diem_id) REFERENCES DIA_DIEM(id));
IF OBJECT_ID('THE') IS NULL CREATE TABLE THE (
    id INT IDENTITY(1,1) PRIMARY KEY, ma VARCHAR(40) NOT NULL UNIQUE, ten NVARCHAR(100) NOT NULL, nhom NVARCHAR(30) NOT NULL);
IF OBJECT_ID('DIA_DIEM_THE') IS NULL CREATE TABLE DIA_DIEM_THE (
    dia_diem_id INT NOT NULL, the_id INT NOT NULL, nguon NVARCHAR(30) DEFAULT N'luat_tu_dong', da_duyet BIT DEFAULT 0,
    CONSTRAINT PK_DiaDiemThe PRIMARY KEY (dia_diem_id, the_id),
    CONSTRAINT FK_DDThe_DD FOREIGN KEY (dia_diem_id) REFERENCES DIA_DIEM(id),
    CONSTRAINT FK_DDThe_The FOREIGN KEY (the_id) REFERENCES THE(id));
GO
-- Nap lai du lieu moi (xoa du lieu bang phu truoc de chay lai duoc)
DELETE FROM DIA_DIEM_THE; DELETE FROM THE; DELETE FROM DIA_DIEM_REVIEW; DELETE FROM DIA_DIEM_ANH;
GO

