INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (6,N'They slice the cooked beef right in front of you. Beef is tender. And very attentive staff',5.0,N'JY Mee',N'6 ngày trước',0.2,N'khong_ro',90,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (7,N'Unfortunately, the food and service were both a major disappointment. Despite all the Obama and Anthony Bourdain hype surrounding this restaurant, the food was, in my opinion, completely average. The dishes lacked the flavour and quality I expected, and the experience did not justify the reputation. The “Obama meal” was enough for one person, but beyond the novelty of ordering the same meal, there was very little that stood out from a culinary perspective. The service was equally disappointing. The staff were not welcoming or particularly attentive, which made the experience feel more transactional than hospitable. The Obama and Bourdain connection makes this worth visiting once for the experience and history, but it unfortunately feels more like a tourist attraction and money-making site than somewhere offering genuinely memorable food. Once was enough for me. I would not return.',1.0,N'AB',N'Thời gian chỉnh sửa: 4 giờ trước',0.01,N'khong_ro',893,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (7,N'딱 먹어보기 경험하기 좋아요. 랜드마크가 되어버린 맛집은 아닙니다. 음식 경험 랜드마크',5.0,N'YOMADTV요맨',N'10 giờ trước',0.01,N'khong_ro',48,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (7,N'여기 왜 와요? 서비스 최악 위생 최악 유명하다고 해서 왔는데 배가 불렀는지 서비스 최악이네요 안내도 제대로 안하고 위로만 올라가라고 5번 들었습니다 올라갔는데 휴지랑 지들 물건 널브러져 있어요 근데 주문도 받으러 안오네요^^ 1층에 자리 다 비어있었는데 실랑이 하는 동안에 1층 자리 다 참^^ 내려가서 앉겠다고 몇번을 말해도 무조건 올라가라고 ^^ 진짜 최악이었습니다!',1.0,N'안몬드리 (마루)',N'13 giờ trước',0.02,N'khong_ro',208,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (7,N'整體食物味道，環境，衛生及價錢合理。 可以一試',3.0,N'Y Leung',N'1 ngày trước',0.03,N'khong_ro',23,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (7,N'Amazing food!! I see why Obama came here!',5.0,N'Nuno Esteves',N'1 ngày trước',0.03,N'khong_ro',41,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (7,N'Bun Cha . Trying the one visited by Obama which is awesome! Has a less sweet taste compared to the other michelin with generous grilled pork belly and mini hamburg. . #vnfoodies #vnfood #buncha #huonglien #obama',5.0,N'Elbert Damian',N'1 ngày trước',0.03,N'khong_ro',211,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Thường đến vì mình hay đi vs gia đình từ bé, nhưng giờ quay lại thì cực thất vọng, đồ ăn thì chế biến cắt xén, đắt, nhân viên thái độ cực thiếu tôn trọng khách hàng, có đọc thì thay đổi đi nhé',1.0,N'Bùi Vũ',N'2 ngày trước',0.07,N'vi',192,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Sao chỗ này họ khống bán cho tư nhân làm nhỉ, Nếu tư nhân họ làm thì chắc chắn là điểm đến ẩm thực tuyệt vời. Nhân viên già quá ko hoạt bát, nói cộc cằn, đồ ăn ko ngon. Ko bao giờ quay lại',2.0,N'cuong trinh',N'2 ngày trước',0.07,N'vi',188,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Chát lượng kém, xe vào sân nhà hàng vẫn mất 50k gửi. K cho chuyền khoản, nếu ck mất thêm 8/% thuế',1.0,N'tuấn đõ ngọc',N'3 ngày trước',0.1,N'vi',97,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Trải nghiệm cực tệ khi lần đầu đến và cũng không muốn quay lại lần 2. Nhà mình đi 8 người (3 trẻ con, 3 ng lớn, 2 ng lớn tuổi) lúc đầu đến đặt 2 suất bánh tôm, 1 nem hồ tây, 1 rau xào, 1 cơm, 1 canh, 3 coca, 1 nước dưa hấu. (Vì chưa biết 1 suất bánh tôm là nhiều hay ít nên gọi tạm trc 2 suất). Nhân viên nhà hàng ra chuẩn bị bàn xong thì mang 2 bát nước chấm & 2 đĩa rau ăn kèm ra, nh khi biết nhà mình đặt 2 suất bánh tôm thì họ thái độ dè bỉu rồi lấy đi 1 bát nc chấm & 1 đĩa rau đi (rau sống còn nát vs dập). Khi lên món mình gọi 2 suất nh nhà hàng để chung 1 đĩa nên hỏi đã đủ chưa mới dk thông báo đấy là 2 suất, mình bảo gọi thêm 2 suất nữa thì nv lại thái độ rằng sao không gọi luôn từ đầu, trong khi các món khác mình đặt cũng chưa lên. NV phục vụ đi qua còn hắt nước bẩn sang chỗ cháu mình nh mãi lúc sau cháu kể mình mới biết. Tiếp đến khi thanh toán họ phán cho câu ở đây chỉ trả tiền mặt không chuyển khoản, cũng may là có mang theo chứ không lại mất công đi rút tiền. Thời đại thanh toán ko dùng tiền mặt nh trừ nhà hàng này ra nhé mọi người, mong cơ quan thuế sớm thanh tra cơ sở này đi ạ.',1.0,N'Thùy Linh Nguyễn Thị',N'3 ngày trước',0.1,N'vi',1104,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Bánh tôm k ngon Nhân viên thì dí bắt oder nhiều lên Thái độ Cơm rang thì khô k nuốt nổi Mình muốn gọi 1 phần bánh tôm để gọi thêm nộm và nem ăn nữa. ( mình đi 3 người ) Nhưng nhân viên dí bắt gọi 2 phần bánh tôm, trả lời khách như bố đời. Kbh có lần 2',1.0,N'Thao Nguyen',N'4 ngày trước',0.13,N'vi',251,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Trải nghiệm tệ chưa từng thấy chỉ được cái view thôi chứ vào ngồi là nóng, chả có quạt điều hoà gì cả. Nhân viên thái độ từ bảo vệ trông xe, bắt khách tự dong ra dong vào chửi xơi xơi vào mặt. Chưa gì đã nói đến chuyện tiền nong, như kiểu sợ người ta quỵt tiền, nhắc đi nhắc lại, mang tiếng bảo vệ mà bắt khách tự dong xe, xếp xe các thứ, chỉ đạo như sếp. Còn bên trong thì món ăn thì đắt nước cũng chả ra sao, mua nước kiểu bị ép. Đồ ăn thì bình thường, không đáng giá tiền, Chung quy ăn để trải nghiệm còn lại sẽ không hao giờ quay lại. Tệ chưa từng thấy',1.0,N'Anh Việt',N'5 ngày trước',0.17,N'vi',556,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Phục vụ hách dịch, đồ ăn tệ, giá đắt kinh khủng, tư vấn theo kiểu bẫy khách hàng. Lần đầu tiên và cũng là lần cuối đến đây. Khách thanh toán thì yêu cầu thanh toán tiền mặt nếu chuyển khoản thì cộng thêm tiền thuế 8%',1.0,N'SuZy',N'5 ngày trước',0.17,N'vi',216,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (8,N'Đi xe đạp đến ăn, lúc vào cửa chính thì ông bảo vệ bảo ra cửa sau, ra cửa sau thì bị 2 ông bảo vệ chửi và để mình đỗ xe r tự trông. Bánh tôn thì giòn nhưng con tôm bé tí, phần đế toàn thấy vị ko khí chứ chẳng thấy bột đâu. Thái độ nhân viên phục vị kém, ns chuyện như muốn đấm chet ng ta. Không có điều hòa, quạt còn già hơn bố t',1.0,N'Dokhanh Van',N'5 ngày trước',0.17,N'vi',329,1,N'SerpApi');
