INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (10,N'📍 Vị trí dễ tìm ngay đầu ngõ trạm ra chợ Hàng Da. Quán không có nhiều không gian ngồi nên khá chật chội vì khách đông, cả người địa phương lẫn khách du lịch. 🍲 một suất đầy đủ như hình bao gồm cả giả cầy và đều có măng ở trong cả giả cầy lẫn bún đậu. Nói chung ăn với măng cũng khá lạ miệng và đỡ ngấy',4.0,N'Jessica Lam',N'4 tháng trước',4.0,N'vi',301,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (10,N'Bún Đậu Yến, hay còn được gọi với tên khác là Bún Đậu Ngõ Trạm, quán buổi trưa rất đông khách. Ảnh mình chụp là suất đầy đủ có giá 90 cá ngày đầu năm 2026. Mọi người nên chú ý khi gọi món, mình không nghĩ suất bún đậu lại có thêm cả bát móng giò giả cầy nên một người ăn là hơi nhiều. Quán nhỏ mà rất đông khách, đi với nhóm bạn thì 3-4 người ngồi 1 bàn là hợp lý, đi đông quá khó phục vụ. Mình đánh giá đồ ăn ổn, hợp khẩu vị, dễ ăn, riêng có mắm tôm là không được ngon lắm.',4.0,N'Chien Nguyen',N'5 tháng trước',5.0,N'vi',474,1,N'SerpApi');
