INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (11,N'Tệ rất tệ cực tệ Lần trải nghiệm hôm nay tại quán ăn này là sự ám ảnh của tôi Lần đầu tiên tôi chứng kiến cảnh khách hàng giành giật đồ ăn Bàn của tôi vào sau bàn của chị khách bàn cạnh nên tôi chứng kiến hết tất cả Khách hàng phản ánh ngồi hơn 1 tiếng ko có đồ ăn mà nhân viên cứ như ko nghe thấy gì Không mang nước Cứ chờ đợi , còn nhân viên cứ mang đồ ăn cho các bàn tới sau Khách bàn khác thì giành đồ ăn trên tay của khách đang lấy phần của họ Quản lý hay các nhân viên trong quán mặc kệ không 1 lời xin lỗi hay nói lời thông cảm Đồ ăn có ngon đến mấy tôi cũng ko dám quay lại 1 lần nào nữa Tôi sợ thật sự đấy',1.0,N'van hong',N'4 ngày trước',0.13,N'vi',614,1,N'SerpApi');
