INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (12,N'Nôm bò khô và nem cuốn, bánh bột lọc ngon',5.0,N'Nguyen Quynh Ngan',N'một tháng trước',1.0,N'vi',41,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (12,N'I was just walking past this shop and had an incredibly unsafe and violating experience. A waiter and a man in a long-sleeve shirt (I’m not sure who he was, but the waiter was talking to him and laughing at what he was doing) began speaking to us in Vietnamese. They quickly became inappropriately touchy, actually sliding their fingers down our arms. Even though I don’t speak Vietnamese, I immediately showed how angry I was, but they just laughed at us. I felt so violated and uncomfortable that I decided to go back and take photos of these two men so I could warn others and help you avoid the same experience. Please stay away from this place, your safety is not worth it.',1.0,N'Ellie Soo',N'một tháng trước',1.0,N'khong_ro',678,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (13,N'Cũng khá ổn',4.0,N'Trang Vo',N'3 ngày trước',0.1,N'vi',11,0,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (13,N'Quán sạch sẽ, bánh mì giòn ngon, sốt vang này vị gần giống bò kho của miền nam mình nên mình khá ưng, pate, xúc xích thì không hợp vị mình lắm. Nhưng vẫn khá ngon so với vị của Hà Nội. Giá cả thì tương đối ổn Sữa đậu nành có tàu phớ cũng khá lạ miệng, mình ưng',5.0,N'linh nguyễn',N'3 ngày trước',0.1,N'vi',260,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (13,N'不錯～不一樣的越南麵包吃法～好吃😋',5.0,N'wawa Wa',N'6 ngày trước',0.2,N'khong_ro',17,0,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (13,N'백종원 스푸파에 나온 그곳이라고 해서 찾아가봄. 너무나도 로컬이여서 뭘 주문해야되나 고민이 잠시 되긴했다. 메인 음식은 솟방? sot vang 이라는 건데 와인 스튜 같은거라고 한다. 솟방 하나만 시켜도 반미 바케뜨가 같이 세트로 딸려 나온다. 그것도 모르고 솟방도 시키고 반미 세트에 스테이크도 같이 주문했다. 하노이 맥주도 하나 주문했고 생각보다 양이 많은거같았으나 다 해치울수 있었다 ㅋㅋㅋ 솟방은 생각보다 맛있고 고기도 비린내 없이, 특히 고수? 도 생각보다 잘 먹혔다. 향이 그렇게 쌔지 않음. 반미는 먹어본 맛이고, 안에 뭐가 들었는진 모르겠는데 이상하게 맛있다. 솟방에 찍어먹어도 맛있었다. 특히 반미를 시키니 바게트를 또 주는데 바게트 안에 솟방을 발라 먹으니 생각보다 괜찮았다. 그냥 내가 만들어먹는 재미가 있는곳인가? 그리고 생각보다 bit tet 이라는 스테이크가 좋았다. 계란도 밑에 깔려있고, 고기도 매우 잘 다져진게 이건 진짜 바게트에 넣어서 먹으라고 준건가? 그런 생각이 들었다. 스테이크가 가장 맛있었던거 같다. sot vang - 50000 vnd bit tet - 80000 vnd banh mi kep - 25000 vnd bia - 20000 vnd 총 175000vnd. 정말 혜자스러운 한끼였다.',4.0,N'Brad',N'Thời gian chỉnh sửa: 2 tuần trước',0.47,N'khong_ro',635,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (13,N'60k 1 bát, quá chát. Được chút bò. Đc mỗi cái nằm trên phố',3.0,N'Phương Nguyễn',N'2 tuần trước',0.47,N'vi',58,1,N'SerpApi');
