INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (14,N'Really solid eel specialty place in Hanoi. The stir-fried glass noodles with eel were excellent, noodles had just the right chewiness, and the eel was well marinated with a nice balance of savory flavor, paired with fresh herbs and a well-balanced sweet and sour dipping sauce. The eel spring rolls (nem lươn) were just as good, crispy on the outside, flavorful filling, no fishy taste at all, you could tell the ingredients were fresh. They also serve a small side soup that helps balance out the richness of the meal. Simple, no-frills setting, very much a traditional local eatery, and service was quick.',5.0,N'Liv The Moment',N'một tuần trước',0.23,N'vi',607,1,N'SerpApi');
