INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (16,N'best egg coffee in town!',5.0,N'Zheng Hang Yee',N'1 giờ trước',0.0,N'khong_ro',24,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (16,N'是否為店家的默契?河內以蛋咖啡聞名的咖啡廳既低調又神秘，朋友說Loading T就在Pho 10轉角的不遠處，Google Map也顯示離Pho 10很近，但來回奔波了Chân Cầm街道兩次，我依舊不得其門而入。最後才恍然大悟，原來眼前看似荒廢的法式殖民風格古宅，Loading T café就藏身在它的二樓。 Loading T的內部陳設如同它古宅外觀般停止在十九世紀末，在微亮的黃光照明與少許透進的陽光下，時間顯得更加緩慢，彷彿置身在這喧囂城市之外，令人不自覺地放空。 沒鎖定蛋咖啡的話，Loading T還有諸多飲品可選，當中特推他們的椰子咖啡，中間的椰奶冰沙打得非常綿密，冰沙如流體般絲滑，易與咖啡完美融合入口。另外，他們軟皮可頌也非常厲害，雖然表皮有別於常見的脆皮可頌，但在軟皮的每一表層皆散發著濃厚奶油香氣，每口都充滿著奶香味，單顆35,000VND，極力推薦一試。',5.0,N'Yi Kang Huang',N'Thời gian chỉnh sửa: 1 ngày trước',0.03,N'vi',390,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (16,N'I absolutely loved Loading T Café. The egg Egg coffee was a real highlight — so creamy and delicious with a lovely hint of cinnamon, I could easily have had another one. I also fell in love with the café’s beautiful, characterful design. It feels effortlessly charming without trying too hard. Such a lovely little stop in Hanoi. Super love♥️',5.0,N'Me Onlyme',N'4 ngày trước',0.13,N'vi',342,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (16,N'Quán Cafe mà những ngày về thăm Vietnam mình thường ghé thăm. Không gian đẹp, luôn tạo cảm giác thật bình yên khi thưởng thức đồ uống ở đây. Anh chị chủ quán cũng như nhân viên rất nhiệt tình. Cafe trứng có thể nói ngon nhất Hà nội, những thúc uống khác cũng rất ngon. Sau 1 năm quay lại, mọi thứ vẫn vậy, không gian, đồ uống … chắc đây cũng chính là 1 trong những lí do thôi thúc mình mỗi năm đều về vn thăm quê hương ❤️ 01.09.2026',5.0,N'Trang Pham',N'Thời gian chỉnh sửa: 4 ngày trước',0.13,N'vi',432,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (16,N'Cocoa Egg Cream, Lime Egg Cream . Really unique hidden gem vintage cafe with awesome egg cream on top of nice cocoa and also very refreshing lime slushy! . #vnfoodies #vncafe #loadingtcafe #eggcream #hiddengen',5.0,N'Elbert Damian',N'5 ngày trước',0.17,N'khong_ro',209,1,N'SerpApi');
