INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (18,N'Vietnamese Egg Coffee, Egg Cream With Autumn Rice . Unique traditional look cafe to hangout with an aircon room and well ventilated. Thinking of better taste of so called claimed to be original egg coffee, unfortunately the egg cream is so flat even no eggy taste. Coffee also not strong and little bit watery. However, the autumn rice give better flavour and texture with crispy rice on top. . #vnfoodies #vncafe #cafegiang #eggcoffee #autumnrice',3.0,N'Elbert Damian',N'10 phút trước',0.0,N'khong_ro',447,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (18,N'Popular spot amongst tourists for Vietnamese coffee. We ordered the egg coffee and iced coffee with condensed milk. The egg coffee had a strong egg custard flavour which was rich and creamy, which was an interesting blend of flavours with the black coffee. Service was quick and decent ambience with natural light and lots of plants.',3.0,N'carbkels',N'2 giờ trước',0.0,N'khong_ro',333,1,N'SerpApi');
