INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (18,N'Theo sở thích thì tôi thấy cafe muối hợp khẩu vị hơn.',5.0,N'Vi Nguyen',N'1 ngày trước',0.03,N'vi',53,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (18,N'아이스커피 에그커피핫 에그비어 마셨어요. 아이스커피 양은 좀적은데 더워서 아아 왕짱맛 에그커피 녹진하니 계란 맛나고 맛있고 분위긴 현지분위기 같아요. 폰충전해도 된다해서 낭낭히 풀충하고 갑니다.',4.0,N'쓰는이',N'1 ngày trước',0.03,N'khong_ro',108,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (19,N'Blackbird Coffee is one of those cafés that feels genuinely focused on coffee rather than simply relying on a nice interior. I enjoyed the overall experience because the atmosphere was relaxed and understated, while the drinks still felt carefully prepared and consistent. The coffee was easily the highlight for me. It had a clean, balanced flavour with enough character to make it interesting without becoming too bitter or overly acidic. I appreciated that the drink tasted like something made with attention rather than rushed through. The aroma was noticeable, the texture was smooth, and the overall cup felt very well put together. I also liked the simplicity of the space. The interior has a minimalist, slightly industrial character that suits the brand well. It feels casual and comfortable rather than overly polished, so it works equally well for a quick coffee, a conversation with a friend, or some quiet time alone. The atmosphere was calm enough that I did not feel pressured to leave quickly. The service was another positive part of the visit. The staff were friendly, efficient, and clearly familiar with the menu. Orders were handled smoothly, and the whole process felt easy from start to finish. What I appreciate most about Blackbird is that it does not try to do too much. The focus stays on good coffee, a pleasant space, and reliable service. That simplicity makes the experience feel more authentic. Overall, Blackbird Coffee is a strong choice in central Hanoi if you care about the quality of the coffee itself. The balanced drinks, relaxed environment, and straightforward service make it somewhere I would happily return to whenever I want a proper coffee break.',5.0,N'Stephen Le',N'3 giờ trước',0.0,N'vi',1693,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (19,N'Blackbird Coffee Chân Cầm nổi bật với tông màu cam ấm áp nép mình trên con phố nhỏ yên bình gần Nhà Thờ Lớn! Cà phê Espresso đậm đà sánh mịn, Cold Brew thơm hương hoa quả và góc ngồi chill ngắm phố cổ!',5.0,N'이영량',N'1 ngày trước',0.03,N'vi',201,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (19,N'Blackbird luôn là một trong những địa điểm yêu thích của tôi để tận hưởng Hà Nội vào sáng sớm. Còn gì tuyệt hơn việc làm một cốc cà phê rồi tiện thể đi ăn sáng ngay gần đó or lại đi cafe tiếp ngay cạnh đó :))) Dù giờ không còn ở Hà Nội nữa, mỗi lần có dịp quay lại, tôi vẫn luôn cố ghé Blackbird.',5.0,N'Đạt Nguyễn Minh',N'2 ngày trước',0.07,N'vi',296,1,N'SerpApi');
