INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (19,N'Best cold brew I have ever had anywhere.',5.0,N'Daniel Sanchez',N'4 ngày trước',0.13,N'khong_ro',40,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (19,N'Quán mở đến 21h30. Không gian nhỏ, ít bàn, có chỗ trong nhà tầng 1, trên gác và ít chỗ bên ngoài ngay cửa vào. Đồ uống hôm mình gọi ko quá ấn tượng (m ko uống cà phê 😃), nước ép dứa dâu gì đó, 70k/ cốc.',5.0,N'Lan Anh Lê',N'5 ngày trước',0.17,N'vi',202,1,N'SerpApi');
