INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (20,N'cốc matcha latte thật sự tệ, bột đánh ko kỹ nên còn cặn và bị đắng chát như pha với nước lọc vậy ko chút mùi sữa nào. Thêm nữa là cái cửa ra ban công tầng 2 bị kẹt nên mở rất khó, đồ uống thì tự bê lên, với sức con gái thì thật sự là nếu ko đặt đồ xuống đất hoặc nhờ khách khác mở cửa hộ thì rất chật vật để đẩy đc cái cửa',2.0,N'06 nca',N'1 ngày trước',0.03,N'vi',322,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (20,N'Quán view đẹp, chỗ ngồi thoáng, có điều hoà mát mẻ. Mình gọi Coldbrew Mận ngon xuất sắc. Miếng mận dẻo mặn đậm vị, kết hợp phong vị cà phê ☕️ thanh rất ngon. Có lẽ là món coldbrew mình thấy ngon nhất :)) Sẽ quay lại thử món Coldbrew Mơ màng nữa :))',5.0,N'Hoang Alex',N'2 tuần trước',0.47,N'vi',248,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (20,N'Nhân viên thờ ơ. Dịch vụ vô cùng kém. Gói bắp rang bơ nó dính chặt vào nhau, tách không được, vừa khô vừa cứng, nhai hơn nhai rơm vẫn bán cho khách. Hỏi đồ uống thì không biết trong đấy có cái gì, có thật là đi bán hàng không vậy???',1.0,N'Đức Anh TRẦN',N'3 tuần trước',0.7,N'vi',232,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (20,N'Phục vụ đáng yêu 🌼',5.0,N'Thu Huỳnh',N'4 tuần trước',0.93,N'vi',18,0,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (21,N'Đã trải nghiệm rất nhiều cơ sở phê la nhưng cơ sở này tệ nhất. Mình đã từng dùng trực tiếp tại quán và cả đặt trên app trung gian nhưng đều phải chờ rất lâu, đơn nhiều không nói nhưng đơn 2 cốc trực tiếp uống tại quán thì tận gần 1 tiếng (lúc sáng sớm và quán chưa hề đông khách nhé), lại còn 1 cốc đã làm xong từ lâu, tan hết đá rồi nhưng không làm tiếp cốc còn lại, cứ để trên quầy đồ chờ. Phải đến khi bạn mình ra giục và canh tại quầy thì nhân viên mới bảo được 1 cốc rồi. Còn đơn đặt qua app thì vô cùng tệ, đặt từ 14h50 mà đến 16h tài xế mới nhận được đủ đơn để giao cho mình, đã thế quán còn giao thiếu 1 phần topping cho mình nữa. Không có sđt, không có thông tin để phản ánh chất lượng',1.0,N'Dung Phạm',N'1 ngày trước',0.03,N'vi',694,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (21,N'Quán lúc nào cũng đông nên đồ ra hơi lâu. Mình luôn gọi Đà Lạt và Tấm, đỉnh của chóp',5.0,N'Vicky',N'3 ngày trước',0.1,N'vi',84,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (21,N'Không nói đến đồ uống vì lúc nào cũng quá lâu. Không gian nóng, hơn 20 người được 1 cái quạt, thái độ nhân viên trả lời khách cụt lủn.',1.0,N'Linnh Thuy',N'3 ngày trước',0.1,N'vi',134,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (21,N'Nhân viên order cho khách thái độ rất tệ, máy order hỏng cũng không báo khách, gọi đồ gì cũng hết món cũng ko chủ động báo cho khách, phải để khách hỏi mới trả lời, nhân viên đứng ở quầy nói chuyện rất đông nhưng khách ra lấy nước cũng gọi 2-3 lần mới thưa 😡 Từng là khách hàng ngồi cơ sở này rất nhiều lần nhưng chắc sẽ không bao giờ quay lại',1.0,N'Mingg Minhh',N'6 ngày trước',0.2,N'vi',343,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (21,N'- Nay qua cửa hàng sử dụng máy order đồ đứng 1 lúc loay hoay ko được nhân viên mới nói máy hỏng, nhân viên nữ rất thái độ, mặt lạnh vs khách như bị bắt đi làm. - Nhờ nv nam mang quạt ra thì kêu ko để ở ngoài được nhưng bên đối diện vẫn dùng, sau có quản lý ra giải thích chỉ để được ở trên bục ko để dưới đường, nhưng ngồi chờ 15p vẫn ko thấy mang ra. - Chờ 20p ko có nước trong khi quán vắng, vào hỏi thì hoá ra quên làm, giục mang quạt ra mới mang, thái độ làm dịch vụ rất kém.',2.0,N'Thủy Tiên Nguyễn',N'một tuần trước',0.23,N'vi',479,1,N'SerpApi');
