INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (22,N'best place in town',5.0,N'Bánh mì Gác',N'10 giờ trước',0.01,N'khong_ro',18,0,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (22,N'Seafood Spaghetti and Spicy Sauce, Bolognese Spaghetti, Bun Cha Ha Noi, Saigon Broken Rice, Lotus Tea with Salted Dry Apricot . Unique multiple stories cafe with a great eastern and western food! Not only hype but its having a great food. Seafood spaghetti really good with generous sliced squid and couple of huge prawns! Bolognese also awesome! Cheesy and having generous sliced ham. On the eastern side, bun cha is amazing! A well known awesome dipping taste which balanced between sweet and savory suddenly struck and brings you back to the Vietnamese restaurant back in SG but made by original recipe! Served with juicy grilled pork belly and mini hamburg. Broken rice also not bad! Tender and juicy pork complimented with a nice sauce and runny sunny side up. Lotus tea with salted dry apricot arranged nicely with a unique taste. Comes with multiple block of jellies to tone down the taste. . #vnfoodies #vnfood #bancong #spaghetti #buncha',5.0,N'Elbert Damian',N'15 giờ trước',0.02,N'khong_ro',946,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (22,N'⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐⭐ 100 STARS OUT OF 10! 🌟🌟🌟 Absolutely one of the best dining experiences we’ve had! Everything was just PERFECT from the food, service, ambiance, and overall experience. If I could give more than 10 stars, I definitely would! 💯 🍽️ THE FOOD — 10/10! The food was absolutely delicious and palatable! Every dish we ordered was flavorful, satisfying, and generously served. The portions are really worth it—maraming serving, so you definitely get your money’s worth. You can tell that they really put effort into making their food taste amazing. We honestly enjoyed every bite! 🤤 👩🏻‍💼 THE SERVICE — EXCEPTIONAL! What made our experience even more special was the staff. Everyone was very accommodating, friendly, and attentive, but special mention to LA, who assisted us during our visit. She was incredibly helpful, approachable, and made sure we were comfortable and well taken care of. ❤️ LA truly gave us excellent customer service—the kind that makes you feel genuinely welcomed and valued as a customer. Her warm and accommodating personality definitely added to the wonderful experience! 📸 THE AMBIANCE — ABSOLUTELY BEAUTIFUL! The place itself is SO BEAUTIFUL and Instagram-worthy! ✨ Every corner is aesthetically pleasing and perfect for photos. The ambiance is relaxing, inviting, and gives such a nice vibe that you’d actually want to stay longer. Overall, this place is a MUST-TRY! Great food, generous servings, beautiful ambiance, and most importantly, amazing people and customer service. Definitely one of those restaurants where you leave feeling happy and satisfied—not just because of the food, but because of the entire experience. 🥰 100 STARS OUT OF 10! 🌟🌟🌟🌟🌟 Highly recommended! We will definitely be coming back and recommending this place to our friends and family. Kudos to the entire team, especially LA, for making our visit extra special! ❤️👏🏻 Love from the Philippines 🇵🇭 Ps: SOBRANG SARAAAAAP!!!',5.0,N'Glamformation Makeup By Jesse',N'1 ngày trước',0.03,N'khong_ro',1939,1,N'SerpApi');
