INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (24,N'Bạn là người của công việc muốn tìm một quán cafe để bàn công việc với đối tác thì đây là điểm lý tưởng. Quán rất gần các văn phòng. Hay một sáng chủ nhật mùa thu, sau bữa sáng ở phở Thìn hay Pizza Connes thì đây là điểm hẹn gặp bạn thân rất tuyệt',5.0,N'Local Guide',N'8 năm trước',96.0,N'vi',247,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (25,N'I stopped by just a few minutes before closing because I urgently needed to use the restroom, and even though I wasn’t a customer and didn’t order anything, the gentleman working there (probably the owner) welcomed me with remarkable kindness. The café itself has a beautiful, calming atmosphere with tastefully arranged decor that immediately leaves a positive impression. What stood out most was how genuinely helpful and polite he was, taking the time to assist me without the slightest hesitation. I even tried to offer a tip out of gratitude, but he firmly refused to accept it. This level of warmth and hospitality is rare, and it turned a simple moment into a memorable experience. I can wholeheartedly recommend this place to anyone in Hanoi looking for a café with true heart and exceptional courtesy.',5.0,N'M0S3S',N'9 tháng trước',9.0,N'vi',810,1,N'SerpApi');
