INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (26,N'Đền Ngọc Sơn nằm trọn trên đảo Ngọc giữa lòng Hồ Hoàn Kiếm, là một di tích lịch sử - văn hóa trọng điểm mang đậm giá trị tâm linh của Thủ đô Hà Nội. Để vào đền, du khách sẽ đi qua Đắc Yêu Môn, Tháp Bút, Đài Nghiên rồi bước qua Cầu Thê Húc đỏ rực nổi bật trên làn nước xanh. Đền thờ Hưng Đạo Đại Vương Trần Quốc Tuấn và Văn Xương Đế Quân, đồng thời là nơi lưu giữ hai tiêu bản rùa Hồ Gươm có giá trị lịch sử và tâm linh to lớn. Không gian bên trong di tích được giữ gìn rất tôn nghiêm, trang trọng và có sự kết hợp hài hòa giữa kiến trúc cổ kính với cảnh quan thiên nhiên. Khi đến tham quan, du khách cần lưu ý ăn mặc lịch sự, kín đáo (áo có tay, quần hoặc váy dài quá gối) để đảm bảo sự tôn kính đối với chốn linh thiêng. Vé vào cửa được bán ở khu vực đầu cầu Thê Húc với mức giá rất hợp lý (khoảng 50.000 VNĐ/người lớn) và có chính sách giảm giá cho học sinh, sinh viên, người cao tuổi. Lượng khách tham quan khá đông vào các ngày cuối tuần hoặc dịp lễ, tết, vì vậy bạn nên chủ động đi vào các khung giờ sáng sớm hoặc ngày giữa tuần để cảm nhận trọn vẹn sự thanh tịnh và không khí cổ kính của di tích.',5.0,N'Thị Quỳnh Phương Lê',N'7 giờ trước',0.01,N'vi',1102,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (26,N'Kleiner Tempel, nicht unbedingt wahnsinnig spektakulär, aber man kann das eben im vorübergehen abhaken.',4.0,N'Blackmarket',N'8 giờ trước',0.01,N'khong_ro',103,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (26,N'50.000 VND - kann man sich auf jeden Fall mal ansehen sollte man in der Nähe sein.',5.0,N'Finnegan Raabe',N'2 ngày trước',0.07,N'khong_ro',82,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (26,N'Đền đc tu sửa bảo trì thường xuyên, vé vào cửa là 50k/người.',4.0,N'Hiền Lương Dương Công',N'2 ngày trước',0.07,N'vi',60,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (26,N'能量不錯的地方，白天跟晚上來都有不一樣的感覺',5.0,N'鄭善方',N'2 ngày trước',0.07,N'khong_ro',22,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (26,N'Hôm qua ngày lễ 2/9 mình được đi tham quan miễn phí tại "Đền Ngọc Sơn" tại quận Hoàn Kiếm Hà Nội. Nếu ngày thường thì các bạn phải mua vé vào là 50.000/1 vé người lớn và 25.000/1 vé cho người già hoặc trẻ em. Phải nói đây là một nơi khá ấn tượng mà các du khách nên đến. • Theo tôi được biết: 👉 Đền NGỌC SƠN – Hà Nội Đền Ngọc Sơn là một di tích lịch sử – văn hóa nổi tiếng của Hà Nội, nằm trên đảo Ngọc giữa Hồ Hoàn Kiếm. Đền được xây dựng từ thời nhà Lý và trải qua nhiều lần tu sửa, mang đậm nét kiến trúc truyền thống Việt Nam. Đền chủ yếu thờ Đức Thánh Trần Hưng Đạo, vị anh hùng dân tộc có công lớn trong các cuộc kháng chiến chống quân Nguyên – Mông, cùng một số nhân vật quan trọng trong lịch sử và văn hóa Việt Nam. Du khách đến đền sẽ đi qua Cầu Thê Húc, cây cầu gỗ sơn đỏ nổi tiếng, có tên mang ý nghĩa là “nơi đón ánh sáng ban mai”. Gần đền còn có Tháp Bút và Đài Nghiên, tượng trưng cho truyền thống hiếu học và coi trọng văn chương của người Việt. Một trong những điểm đặc biệt của Đền Ngọc Sơn là hai cụ rùa khổng lồ được bảo quản và trưng bày bên trong đền. Đây là những mẫu vật rùa Hồ Gươm quý hiếm, gắn liền với truyền thuyết về Rùa Vàng và vua Lê Lợi. Theo truyền thuyết, sau khi đánh thắng giặc, vua Lê Lợi đã trả lại thanh gươm thần cho Rùa Vàng tại Hồ Hoàn Kiếm. Vì vậy, hình ảnh rùa ở Đền Ngọc Sơn mang ý nghĩa đặc biệt, gắn với lịch sử và truyền thuyết của Hồ Gươm. Ngày nay, Đền Ngọc Sơn không chỉ là một điểm tham quan nổi tiếng mà còn là một biểu tượng văn hóa của Hà Nội, gắn liền với lịch sử, truyền thuyết và vẻ đẹp của Hồ Hoàn Kiếm 👉 Bản dịch sang Tiếng Anh • NGỌC SƠN Temple is a famous historical and cultural site in Hanoi, located on Ngoc Island in the middle of Hoan Kiem Lake. The temple was originally built during the Ly Dynasty and has been renovated several times. It features traditional Vietnamese architecture. The temple mainly worships Tran Hung Dao, a national hero who played an important role in the wars against the Mongol invasions, as well as several other important figures in Vietnamese history and culture. Visitors enter the temple through The Huc Bridge, a famous red wooden bridge whose name means “the place where the morning sunlight shines.” Near the temple are Pen Tower and Ink Slab, which represent the importance of literature and learning. One of the most interesting features of Ngoc Son Temple is the two preserved giant turtles from Hoan Kiem Lake displayed inside the temple. These turtles are believed to be Yangtze giant softshell turtles, a rare species associated with the legendary Golden Turtle of Hoan Kiem Lake. Their presence reminds visitors of the famous legend of King Le Loi, who is said to have returned a magical sword to the Golden Turtle in the lake after defeating the enemy. Today, Ngoc Son Temple is not only a popular tourist attraction but also an important cultural symbol of Hanoi, closely connected with the history, legends, and beauty of Hoan Kiem Lake.',5.0,N'Honey Nguyen',N'2 ngày trước',0.07,N'vi',2949,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (27,N'Địa điểm du lịch lịch sử đáng ghé thăm',5.0,N'22.Thảo Nhi',N'3 giờ trước',0.0,N'vi',38,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (27,N'I recently had a suit custom-made here, and I’m extremely happy with the result. From the first consultation to the final fitting, the whole experience was professional, friendly, and attentive. The staff took the time to understand exactly what I wanted and carefully measured every detail to make sure the suit would fit my body perfectly. I really appreciated their attention to detail and the helpful advice on choosing the fabric, color, and style. When I received the finished suit, I was genuinely impressed. The fit is excellent, the fabric looks beautiful, and the overall craftsmanship is much better than I expected. The suit feels comfortable to wear while still looking elegant and sophisticated. What I liked most was that the team clearly cared about making sure I was satisfied rather than simply finishing the order quickly. They were patient with my requests and made adjustments when necessary. If you are looking for a reliable place for custom tailoring, I would definitely recommend this shop. The quality, service, and attention to detail are all excellent. I’m very pleased with my suit and will definitely come back for another custom-made outfit in the future. A great experience from start to finish!',5.0,N'Dinh Dinh',N'3 giờ trước',0.0,N'khong_ro',1227,1,N'SerpApi');
