INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (29,N'非常小，湖邊很臭，不值得來這。 入口有阿姨出租超貴衣裙騙你進入參觀要遮擋，一堆導遊無袖短褲照樣進出，根本沒差。',1.0,N'霹靂炫',N'1 ngày trước',0.03,N'khong_ro',55,1,N'SerpApi');
INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (29,N'We got to this pagoda using that terrible red hop‑on‑hop‑off bus — the one we wasted so much money on, yet rode for less than two hours total. That said, Tran Quoc Pagoda itself is absolutely authentic. This is a genuine Buddhist place of worship, and it is one of Hanoi’s oldest pagodas. I really enjoyed exploring the grounds. It feels so peaceful, even with the hot weather and sudden rain showers; visiting here felt like stepping into a completely different world. A quick tip for visitors: make sure you wear long trousers or proper modest clothing. We had no idea where the bus would take us and just followed the map, so I was under‑dressed. An elderly local woman approached me to sell a leg cover wrap. It was an awkward moment at the time, but now it makes a funny little souvenir. I adore the soft scent of incense filling the air. This visit gave me a real sense of what Vietnamese temple culture is all about. I was pleasantly surprised by the entry fees. Some temples are even completely free. Where there is a charge, the small difference between local and foreign‑visitor pricing is very minimal. Coming from Indonesia, I was shocked by how affordable everything is here. I would absolutely come back to this pagoda, but next time, definitely not on that bus 😒',5.0,N'Yeni Tira Wati',N'1 ngày trước',0.03,N'khong_ro',1277,1,N'SerpApi');
