INSERT INTO DIA_DIEM_REVIEW (dia_diem_id,noi_dung,so_sao,nguoi_viet,thoi_gian_goc,tuoi_review_thang,ngon_ngu,so_ky_tu,dung_cho_ai,nguon) VALUES (30,N'After visiting the train street, we decided to just walk all over the place, and found this church. Amazing structure and ao many people. Nice time we spent afternoon here and go back to our hotel, walking. It''s my fate to be with european 🤣 My bf was not really impressed, they have a lot back home. But its stimm impressive for me. Just to see the outside is free, too bad its close when we were there. If there is next time, we would line to see the inside too.',5.0,N'Yeni Tira Wati',N'1 ngày trước',0.03,N'khong_ro',464,1,N'SerpApi');
